#include <vector>
#include <algorithm>

struct Point_2 {
    double x, y;
    Point_2() : x(0), y(0) {}
    Point_2(double x, double y) : x(x), y(y) {}
};

std::vector<Point_2> convex_hull_graham(std::vector<Point_2> points) {
    int n = points.size();
    if (n <= 1) return points;

    // Find the point with minimum y-coordinate (and minimum x-coordinate in case of tie)
    int start = 0;
    for (int i = 1; i < n; i++) {
        if (points[i].y < points[start].y || 
            (points[i].y == points[start].y && points[i].x < points[start].x)) {
            start = i;
        }
    }

    // Move the starting point to the beginning
    std::swap(points[0], points[start]);

    // Sort points by polar angle with respect to the starting point
    Point_2 pivot = points[0];
    std::sort(points.begin() + 1, points.end(), 
        [&pivot](const Point_2& a, const Point_2& b) {
            double cross = (a.x - pivot.x) * (b.y - pivot.y) - (a.y - pivot.y) * (b.x - pivot.x);
            if (cross != 0) return cross > 0;  // Counter-clockwise

            // If collinear, closer point comes first
            double dist_a = (a.x - pivot.x) * (a.x - pivot.x) + (a.y - pivot.y) * (a.y - pivot.y);
            double dist_b = (b.x - pivot.x) * (b.x - pivot.x) + (b.y - pivot.y) * (b.y - pivot.y);
            return dist_a < dist_b;
        });

    // Graham scan
    std::vector<Point_2> hull;
    hull.push_back(points[0]);
    hull.push_back(points[1]);

    for (int i = 2; i < n; i++) {
        while (hull.size() >= 2) {
            Point_2 top = hull.back();
            hull.pop_back();
            Point_2 second_top = hull.back();

            double cross = (top.x - second_top.x) * (points[i].y - second_top.y) - 
                          (top.y - second_top.y) * (points[i].x - second_top.x);

            if (cross > 0) {  // Counter-clockwise turn
                hull.push_back(top);
                break;
            }
        }
        hull.push_back(points[i]);
    }

    return hull;
}

int main() {
    std::vector<Point_2> points = {{0,0}, {1,0}, {1,1}, {0,1}};
    auto hull = convex_hull_graham(points);
    return 0;
}

